   120	/// Generic expression descent: handle the pattern-introducing control-flow forms
   121	/// (`for`/`match`/`if let`/`while let`/closures) + nested blocks + macros, and
   122	/// recurse into all other children.
   123	fn walk_expr(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
   124	    match nid.kind.as_str() {
   125	        "block" => {
   126	            walk_stmt_or_block(b, path, nid, scope, ctx);
   127	            return;
   128	        }
   129	        "macro_invocation" => {
   130	            walk_macro_invocation(b, path, nid, scope, ctx);
   131	            // fall through to descend (args may contain more)
   132	        }
   133	        "closure_expression" => {
   134	            walk_closure(b, path, nid, scope, ctx);
   135	            return;
   136	        }
   137	        "for_expression" => {
   138	            walk_for(b, path, nid, scope, ctx);
   139	            return;
   140	        }
   141	        "match_expression" => {
   142	            walk_match(b, path, nid, scope, ctx);
   143	            return;
   144	        }
   145	        "if_expression" | "while_expression" => {
   146	            walk_if_while(b, path, nid, scope, ctx);
   147	            return;
   148	        }
   149	        _ => {}
   150	    }
