    42	/// The byte offset of the FIRST occurrence of `needle` in `src` (the test marks
    43	/// a call/use site by its source text).
    44	fn byte_of(src: &str, needle: &str) -> usize {
    45	    src.find(needle)
    46	        .unwrap_or_else(|| panic!("needle {needle:?} not found in source"))
    47	}
