    49	/// The byte offset of the Nth (0-based) occurrence of `needle`.
    50	fn byte_of_nth(src: &str, needle: &str, n: usize) -> usize {
    51	    let mut start = 0;
    52	    for _ in 0..n {
    53	        let i = src[start..]
    54	            .find(needle)
    55	            .unwrap_or_else(|| panic!("needle {needle:?} occurrence {n} not found"));
    56	        start += i + needle.len();
    57	    }
    58	    start
    59	        + src[start..]
    60	            .find(needle)
