    90	fn resolve_crate_path(
    91	    g: &ScopeGraph,
    92	    fs: &BTreeMap<String, ParsedFile>,
    93	    edition: u16,
    94	    root_path: &str,
    95	    segs: &[&str],
    96	    ns: NamespaceId,
    97	) -> Resolution {
    98	    let fid = file_id(fs, root_path).expect("file id");
    99	    // Anchor `crate::` from any scope in that file.
   100	    let from = enclosing_scope(g, fid, 0).expect("root scope");
   101	    let pol = RustPolicy::new(g, edition);
